contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient) public payable {
        require(recipient != address(0), "recipient must be nonzero");
        require(recipient != address(c), "recipient cannot be c");
        require(address(c) != address(this), "c cannot be the test contract");

        // Fund c so the balance logic is non-trivial.  msg.sender is this test contract,
        // which is the owner deployed with c.
        (bool funded, ) = address(c).call{value: 1 wei}("");
        require(funded);

        uint256 beforeC = address(c).balance;

        // Drive the contract: owner calls withdrawAll to recipient.
        c.withdrawAll(recipient);

        uint256 afterC = address(c).balance;

        // The single general rule, checked entirely through public surface:
        // a successful owner withdrawal empties c's balance (initial balance at least 1 wei),
        // so the new balance must be exactly 0 wei and cannot exceed the pre-call balance.
        assert(afterC == 0 && afterC <= beforeC);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 amount) public payable {
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "test contract needs enough balance");
        require(recipient != address(0), "recipient must be nonzero");
        require(recipient != address(c), "recipient cannot be c");
        require(recipient != address(this), "recipient cannot be the test contract");

        // Fund c so that the withdrawal moves actual Ether.  msg.sender is this
        // test contract, which is also c's owner because the constructor took
        // the deployer as owner.
        c.fallback{value: amount}();

        uint256 beforeBalance = address(c).balance;

        // Drive the owner-only withdrawal.  This is a plain top-level state-changing
        // call on c.
        c.withdrawAll(recipient);

        uint256 afterBalance = address(c).balance;

        // General rule: after a successful owner withdrawal, c holds no Ether at all.
        assert(afterBalance == 0 && beforeBalance >= amount);
    }

    receive() external payable {}
}

contract InvMutTest {
