        require(address(this).balance >= amount, "test contract needs enough balance");
        require(recipient != address(0), "recipient must be nonzero");
        require(recipient != address(c), "recipient cannot be c");
        require(recipient != address(this), "recipient cannot be the test contract");

        // Fund c. Sending Ether via a plain call triggers c's fallback().
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "funding c failed");

        uint256 beforeBalance = address(c).balance;
        uint256 recipientBefore = recipient.balance;

        // Owner-only withdrawal; msg.sender is this test contract, which deployed c
        // and is therefore c's owner.
        c.withdrawAll(recipient);

        uint256 afterBalance = address(c).balance;
        uint256 recipientAfter = recipient.balance;

        // General rule: after a successful owner withdrawal, c holds no Ether at all,
        // and the recipient receives exactly the entire pre-call balance of c.
        assert(afterBalance == 0 && recipientAfter == recipientBefore + beforeBalance);
    }

    receive() external payable {}
}

